/* Sorted names bound the search even as the original corpus grows. */
static inline unsigned a2_actor_source_lower_bound(const char *key){
 unsigned lo=0,hi=A2_ACTOR_SOURCE_COUNT;
 while(lo<hi){unsigned mid=lo+(hi-lo)/2;
  if(strncmp(a2_actor_source_layouts[mid].key,key,32)<0)lo=mid+1;else hi=mid;}
 return lo;
}
static inline unsigned a2_actor_source_find(const char *key,const uint8_t hash[32]){
 for(unsigned j=a2_actor_source_lower_bound(key);j<A2_ACTOR_SOURCE_COUNT &&
     !strncmp(a2_actor_source_layouts[j].key,key,32);j++)
  if(!memcmp(a2_actor_source_layouts[j].hash,hash,32))return j;
 return A2_ACTOR_SOURCE_COUNT;
}
